auto func (auto value){  
    int sum = 0;  
    size_t length = 0;  
    for(auto& i : value) {  
        sum += i;  
        length += i.size();  
    }  
    return make_pair(sum, length);  
}

auto func (auto value){ 
    auto min_value = value;
    for(const auto& elem : value){
        if(elem.size() < min_value.size()){
            min_value = elem;
        }
    }
    return min_value.size();
}

auto func (auto value){ 
    return *std::min_element(begin(value), end(value), [](const auto& a, const auto& b) { return size(a) < size(b); });
}
